begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
insert into auth.users(id,email) values ('74000000-0000-4000-8000-000000000001','ori74@example.invalid');
insert into condominiums(id,manager_id,name,address) values ('74000000-0000-4000-8000-000000000001','74000000-0000-4000-8000-000000000001','Synthetic ORI74','Synthetic address');
select set_config('ori74.slug',(select slug from condominiums where id='74000000-0000-4000-8000-000000000001'),true);
set local role service_role;
select set_config('ori74.created',(select occurrence_id::text from register_public_occurrence_with_suggestion(current_setting('ori74.slug'),'Synthetic reporter','11900000000','Synthetic unit','Cheiro de gás no hall do 5º andar','Hall','urgent','Menciona gás: risco à segurança.','rules')),true);
select throws_ok($$select register_public_occurrence(current_setting('ori74.slug'),'Synthetic reporter','11900000000','Synthetic unit','Legacy call')$$,'42501',null,'Old server entry cannot bypass required suggestion');
select throws_ok($$select register_public_occurrence_with_suggestion(current_setting('ori74.slug'),'Synthetic reporter','11900000000','Synthetic unit','Synthetic description',null,'normal','Sem sinal de risco no relato.','rules')$$,'22023',null,'Reject location is required');
select throws_ok($$select register_public_occurrence_with_suggestion(current_setting('ori74.slug'),'Synthetic reporter','11900000000','Synthetic unit','Synthetic description',' ','normal','Sem sinal de risco no relato.','rules')$$,'22023',null,'Reject location is nonblank');
select throws_ok($$select register_public_occurrence_with_suggestion(current_setting('ori74.slug'),'Synthetic reporter','11900000000','Synthetic unit','Synthetic description',repeat('x',201),'normal','Sem sinal de risco no relato.','rules')$$,'22023',null,'Reject location length');
select throws_ok($$select register_public_occurrence_with_suggestion(current_setting('ori74.slug'),'Synthetic reporter','11900000000','Synthetic unit','Synthetic description','Hall',null,'Sem sinal de risco no relato.','rules')$$,'22023',null,'Reject priority required');
select throws_ok($$select register_public_occurrence_with_suggestion(current_setting('ori74.slug'),'Synthetic reporter','11900000000','Synthetic unit','Synthetic description','Hall','low','Sem sinal de risco no relato.','rules')$$,'22023',null,'Reject low priority unsupported');
select throws_ok($$select register_public_occurrence_with_suggestion(current_setting('ori74.slug'),'Synthetic reporter','11900000000','Synthetic unit','Synthetic description','Hall','invalid','Sem sinal de risco no relato.','rules')$$,'22023',null,'Reject priority allowlist');
select throws_ok($$select register_public_occurrence_with_suggestion(current_setting('ori74.slug'),'Synthetic reporter','11900000000','Synthetic unit','Synthetic description','Hall','normal',null,'rules')$$,'22023',null,'Reject reason required');
select throws_ok($$select register_public_occurrence_with_suggestion(current_setting('ori74.slug'),'Synthetic reporter','11900000000','Synthetic unit','Synthetic description','Hall','normal','Menciona gás: risco à segurança.','rules')$$,'22023',null,'Reject normal reason combination');
select throws_ok($$select register_public_occurrence_with_suggestion(current_setting('ori74.slug'),'Synthetic reporter','11900000000','Synthetic unit','Synthetic description','Hall','normal','Sem sinal de risco no relato.',null)$$,'22023',null,'Reject source required');
select throws_ok($$select register_public_occurrence_with_suggestion(current_setting('ori74.slug'),'Synthetic reporter','11900000000','Synthetic unit','Synthetic description','Hall','normal','Sem sinal de risco no relato.','ai')$$,'22023',null,'Reject AI source not implemented');
select throws_ok($$select register_public_occurrence_with_suggestion(current_setting('ori74.slug'),'Synthetic reporter','11900000000','Synthetic unit','Synthetic description','Hall','normal','Sem sinal de risco no relato.','invalid')$$,'22023',null,'Reject source allowlist');
select throws_ok($$select register_public_occurrence_with_suggestion(current_setting('ori74.slug'),'Synthetic reporter','11900000000','Synthetic unit','Synthetic description','Hall','urgent','Sem sinal de risco no relato.','rules')$$,'22023',null,'Reject urgent normal reason');
select throws_ok($$select register_public_occurrence_with_suggestion(current_setting('ori74.slug'),'Synthetic reporter','11900000000','Synthetic unit','Synthetic description','Hall','urgent','Menciona : risco à segurança.','rules')$$,'22023',null,'Reject empty urgent term');
select throws_ok($$select register_public_occurrence_with_suggestion(current_setting('ori74.slug'),'Synthetic reporter','11900000000','Synthetic unit','Synthetic description','Hall','urgent','Menciona gás: risco à segurançaX','rules')$$,'22023',null,'Reject urgent reason punctuation');
select throws_ok($$select register_public_occurrence_with_suggestion(current_setting('ori74.slug'),'Synthetic reporter','11900000000','Synthetic unit','Synthetic description','Hall','urgent',repeat('x',301),'rules')$$,'22023',null,'Reject reason length');
reset role;
select ok((select location='Hall' and suggested_priority='urgent' and suggestion_reason='Menciona gás: risco à segurança.' and suggestion_source='rules' and suggestion_at>=transaction_timestamp() from occurrences where id=current_setting('ori74.created')::uuid),'Original suggestion and real location persist with server time');
select ok((select final_priority is null and priority_decided_at is null and decided_priority is null and decided_suggested_priority is null and priority_change_reason is null and category is null and ai_failure_reason is null from occurrences where id=current_setting('ori74.created')::uuid),'No human decision or extra classification is invented');
select is((select count(*) from occurrence_events where occurrence_id=current_setting('ori74.created')::uuid),1::bigint,'Only registration history exists');
select ok((select not is_human_action and priority_snapshot is null from occurrence_events where occurrence_id=current_setting('ori74.created')::uuid),'Registration snapshot does not invent human priority');
select throws_ok($$update occurrences set suggested_priority='normal' where id=current_setting('ori74.created')::uuid$$,'42501','Original occurrence suggestion is immutable.','Even definer owner cannot overwrite suggested_priority through ordinary updates');
select throws_ok($$update occurrences set suggestion_reason='Overwrite' where id=current_setting('ori74.created')::uuid$$,'42501','Original occurrence suggestion is immutable.','Even definer owner cannot overwrite suggestion_reason through ordinary updates');
select throws_ok($$update occurrences set suggestion_source='ai' where id=current_setting('ori74.created')::uuid$$,'42501','Original occurrence suggestion is immutable.','Even definer owner cannot overwrite suggestion_source through ordinary updates');
select throws_ok($$update occurrences set suggestion_at=clock_timestamp()+interval '1 hour' where id=current_setting('ori74.created')::uuid$$,'42501','Original occurrence suggestion is immutable.','Even definer owner cannot overwrite suggestion_at through ordinary updates');
select lives_ok($$update occurrences set final_priority='normal' where id=current_setting('ori74.created')::uuid$$,'Original suggestion guard does not freeze separate final priority');
insert into occurrences(id,condominium_id,origin,channel,description) values ('74000000-0000-4000-8000-000000000002','74000000-0000-4000-8000-000000000001','manager_panel','phone','Legacy synthetic row');
select throws_ok($$update occurrences set suggested_priority='normal',suggestion_reason='Sem sinal de risco no relato.',suggestion_source='rules',suggestion_at=clock_timestamp() where id='74000000-0000-4000-8000-000000000002'$$,'42501',null,'Legacy missing suggestion is not silently backfilled');
select ok((select suggested_priority is null and suggestion_at is null from occurrences where id='74000000-0000-4000-8000-000000000002'),'Legacy data remains unchanged');
set local role anon;
select throws_ok($$update occurrences set suggestion_reason='Overwrite' where id=current_setting('ori74.created')::uuid$$,'42501',null,'anon cannot mutate original suggestion');
reset role;
select ok(not has_function_privilege('anon','public.register_public_occurrence_with_suggestion(text,text,text,text,text,text,text,text,text)','execute'),'anon new entry privilege');
select ok(not has_function_privilege('anon','public.register_public_occurrence(text,text,text,text,text)','execute'),'anon old entry revoked');
set local role authenticated;
select throws_ok($$update occurrences set suggestion_reason='Overwrite' where id=current_setting('ori74.created')::uuid$$,'42501',null,'authenticated cannot mutate original suggestion');
reset role;
select ok(not has_function_privilege('authenticated','public.register_public_occurrence_with_suggestion(text,text,text,text,text,text,text,text,text)','execute'),'authenticated new entry privilege');
select ok(not has_function_privilege('authenticated','public.register_public_occurrence(text,text,text,text,text)','execute'),'authenticated old entry revoked');
set local role service_role;
select throws_ok($$update occurrences set suggestion_reason='Overwrite' where id=current_setting('ori74.created')::uuid$$,'42501',null,'service_role cannot mutate original suggestion');
reset role;
select ok(has_function_privilege('service_role','public.register_public_occurrence_with_suggestion(text,text,text,text,text,text,text,text,text)','execute'),'service_role new entry privilege');
select ok(not has_function_privilege('service_role','public.register_public_occurrence(text,text,text,text,text)','execute'),'service_role old entry revoked');
select ok(prosecdef and proconfig=array['search_path=""'],'New entry has fixed definer search path') from pg_proc where oid='public.register_public_occurrence_with_suggestion(text,text,text,text,text,text,text,text,text)'::regprocedure;
select * from finish();
rollback;
